head.script:
scwin.onpageload = function() {
	inputCalendar1.setValue("20180505");
	inputCalendar2.setValue("20180505");
}		
scwin.simulateWrapper = function(target, type, options) {
	WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
	scwin.simulateWrapper("#inputCalendar2_input", "key-sequence", {
		sequence: "20180505"
	});
}

scwin.isInputTextSelected = function() {
	var inputElem = WebSquare.wUnit.getDomById("inputCalendar1_input");
	if (document.activeElement !== inputElem) {
		return false;
	}
	// 선택 영역의 시작과 끝이 다르면 텍스트가 선택된 상태
	return inputElem.selectionStart !== inputElem.selectionEnd;
}

scwin.checkVal = function() {
	return scwin.isInputTextSelected();
}

scwin.unitTest = function() {
	//Unit test
	WebSquare.wUnit.start();
	//Test step 1. 샘플실행 후 왼쪽의 inputCalendar를 클릭하고 8자리를 입력한다.
	//1. After running the sample, click inputCalendar on the left and enter 8 digits.
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar2_input').focus()");
	WebSquare.wUnit.addCommand("pause", "100");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar2_input').click()");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
	WebSquare.wUnit.addCommand("pause", "1000");

	WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#inputCalendar1_input').hasClass('w2inputCalendar_focus')", "true");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");

	//Run and Stop test
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest();
